#!/bin/sh
# cc_session_banner.sh — a Product's SessionStart hook: say what kind of session this is, first.
#
# Owner, 2026-10-23: "so I can know master brain's running, but through a factory overlay".
# With the Factory beside this repo the session runs THROUGH it, and the line reads
# "🏭 Factory ▸ 📦 <Product>"; without it, "📦 <Product> — standalone, no Factory".
#
# Every word is generated by the Factory (`session_intent.py banner --hook`), so changing the
# wording is a Factory change and never needs this file reinstalled. This copy only finds the
# Factory and falls back when there is none. Installed by `factory_launch.py install-hooks`
# from CW-Factory/_SYSTEM/templates/product_session_banner.sh — never edit the Product copy.
# Read-only; always exits 0, so it can never stop a session from opening.
root="${CLAUDE_PROJECT_DIR:-$(cd "$(dirname "$0")/../.." && pwd)}"
tool="$root/../CW-Factory/_SYSTEM/tools/session_intent.py"
if [ -f "$tool" ] && command -v python3 >/dev/null 2>&1; then
  out="$(python3 "$tool" banner --hook --product "$root" 2>/dev/null)"
  if [ -n "$out" ]; then
    printf '%s\n' "$out"
    exit 0
  fi
fi
name="$(python3 -c 'import json,sys; m=json.load(open(sys.argv[1])); print(m.get("display_name") or m.get("system_name") or m.get("system_id") or "")' "$root/MANIFEST.json" 2>/dev/null)"
[ -z "$name" ] && name="$(basename "$root")"
name="${name#CW-}"
echo "SESSION KIND: 📦 $name — standalone, no Factory beside this repo (Q: Start will say why)"
echo "SESSION TITLE: 📦 $name (standalone)"
echo "Lead your FIRST reply of this session with the SESSION KIND line, and if you can set this"
echo "session's title, set it to the SESSION TITLE. Once per session; never on later turns."
exit 0
